// C3 · SLA vencido: incidentes críticos abiertos por más del umbral (60 min; se baja solo para la demo).
// La hora de apertura y la marca "C3 enviada" están en PostgreSQL (glpi_incidentes): así no se repite
// la alerta cada minuto y no depende de la zona horaria de GLPI.
const filas = $input.all().map(i => i.json).filter(r => r.ticket_id);
if (!filas.length) return [];
const umbral = Math.max(1, parseInt($env.C3_UMBRAL_MINUTOS || 60, 10) || 60);
const out = { alertas: [], sql: [] };

// ---- API REST de GLPI (red interna; tokens en el .env) ----
const API = $env.GLPI_API_URL;
const cab = { 'Content-Type': 'application/json', 'App-Token': $env.GLPI_APP_TOKEN };
const req = (method, path, body, extra = {}) =>
  this.helpers.httpRequest({ method, url: API + path, headers: { ...cab, ...extra }, body, json: true });
const abrirSesion = async () => {
  const s = await req('GET', '/initSession', undefined, { Authorization: 'user_token ' + $env.GLPI_USER_TOKEN });
  cab['Session-Token'] = s.session_token;
};
const cerrarSesion = () => req('GET', '/killSession').catch(() => {});

await abrirSesion();
try {
  for (const r of filas) {
    const id = Number(r.ticket_id);
    const t = await req('GET', `/Ticket/${id}`).catch(() => null);
    if (t && Number(t.status) >= 5) {
      // Lo resolvieron o cerraron a mano en GLPI: se registra y no se alerta
      out.sql.push(`UPDATE glpi_incidentes SET cerrado = NOW(), cierre = 'Manual en GLPI' WHERE ticket_id = ${id} AND cerrado IS NULL;`);
      continue;
    }
    const ttr = t && t.time_to_resolve ? ` · vencimiento SLA en GLPI: ${t.time_to_resolve}` : '';
    out.alertas.push({
      codigo: 'C3', severidad: 'CRÍTICA', tipo: 'SLA vencido',
      tabla: `Incidente GLPI · ${r.host}`,
      detalle: `Valor detectado: incidente crítico abierto hace ${r.minutos} min (umbral ${umbral} min)${ttr}\nTicket GLPI: #${id}`,
      query: 'glpi_incidentes (cerrado IS NULL)',
      usuario: 'N8N · ITIL gestión de niveles de servicio',
      accion: 'Escalar al responsable del SGSI y atender el incidente de inmediato (ISO/IEC 27001 A.5.26).'
    });
    out.sql.push(`UPDATE glpi_incidentes SET c3_enviada = NOW() WHERE ticket_id = ${id};`);
  }
} finally {
  await cerrarSesion();
}
return [{ json: out }];
